namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public string ImageUrl { get; set; } = string.Empty;
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }

    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<RecipeCategory> _categories =
    [
        new() { Name = "Breakfast", Description = "Start your day with delicious morning meals", Icon = "🥞" },
        new() { Name = "Lunch", Description = "Midday meals to keep you going", Icon = "🥗" },
        new() { Name = "Dinner", Description = "Hearty evening dishes for the whole family", Icon = "🍝" },
        new() { Name = "Desserts", Description = "Sweet treats and indulgent finishes", Icon = "🍰" },
        new() { Name = "Snacks", Description = "Quick bites for any time of day", Icon = "🍿" },
        new() { Name = "Drinks", Description = "Refreshing beverages and cocktails", Icon = "🍹" },
    ];

    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
                Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "2 tsp baking powder", "¼ tsp salt", "3 tbsp melted butter"],
                Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just blended.", "Heat a griddle over medium heat and grease lightly.", "Pour ¼ cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown.", "Serve with maple syrup and fresh berries."],
            },
            new()
            {
                Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Description = "A crisp, tangy salad with homemade Caesar dressing.",
                Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "2 tbsp olive oil", "1 tbsp lemon juice", "1 clove garlic", "1 tsp Dijon mustard", "1 anchovy fillet"],
                Steps = ["Wash and chop romaine lettuce.", "Blend garlic, anchovy, mustard, lemon juice, and olive oil for the dressing.", "Toss lettuce with dressing.", "Top with croutons and shaved parmesan.", "Serve immediately."],
            },
            new()
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Description = "A rich and hearty Italian meat sauce served over spaghetti.",
                Ingredients = ["400g spaghetti", "500g ground beef", "1 onion", "2 cloves garlic", "400g crushed tomatoes", "2 tbsp tomato paste", "1 tsp oregano", "Salt and pepper to taste"],
                Steps = ["Cook spaghetti according to package directions.", "Sauté diced onion and garlic in olive oil.", "Add ground beef and cook until browned.", "Stir in crushed tomatoes, tomato paste, and oregano.", "Simmer for 20 minutes, stirring occasionally.", "Season with salt and pepper.", "Serve sauce over spaghetti with parmesan."],
            },
            new()
            {
                Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Decadent individual cakes with a molten chocolate center.",
                Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "50g flour", "Pinch of salt", "Butter and cocoa for ramekins"],
                Steps = ["Preheat oven to 220°C (425°F).", "Melt chocolate and butter together.", "Whisk eggs and sugar until thick and pale.", "Fold chocolate mixture into eggs.", "Sift in flour and salt, fold gently.", "Pour into greased ramekins.", "Bake for 12 minutes until edges are set but center is soft.", "Invert onto plates and serve immediately."],
            },
            new()
            {
                Id = 5, Title = "Guacamole", Category = "Snacks",
                Description = "Fresh and zesty avocado dip, perfect with tortilla chips.",
                Ingredients = ["3 ripe avocados", "1 lime, juiced", "½ onion, diced", "1 tomato, diced", "2 tbsp fresh cilantro", "1 jalapeño, minced", "Salt to taste"],
                Steps = ["Halve avocados and remove pits.", "Mash avocado in a bowl to desired consistency.", "Stir in lime juice, onion, tomato, cilantro, and jalapeño.", "Season with salt.", "Serve with tortilla chips."],
            },
            new()
            {
                Id = 6, Title = "Mango Smoothie", Category = "Drinks",
                Description = "A creamy tropical smoothie bursting with mango flavor.",
                Ingredients = ["2 cups frozen mango chunks", "1 banana", "1 cup yogurt", "½ cup orange juice", "1 tbsp honey"],
                Steps = ["Add all ingredients to a blender.", "Blend until smooth and creamy.", "Pour into glasses and serve immediately."],
            },
            new()
            {
                Id = 7, Title = "Avocado Toast", Category = "Breakfast",
                Description = "Simple yet satisfying — creamy avocado on crispy toast.",
                Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Red pepper flakes", "Salt and pepper", "2 eggs (optional)"],
                Steps = ["Toast the bread until golden and crispy.", "Mash avocado with lemon juice, salt, and pepper.", "Spread mashed avocado on toast.", "Top with red pepper flakes.", "Optionally, add a poached or fried egg on top."],
            },
        ];
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = submission.Description,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

