@page "/category/{CategoryName}"
@using RecipeHub.Services

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category yet. <a href="submit">Submit one!</a></div>
}
else
{
    <h1 class="mb-4">@CategoryName Recipes</h1>
    <div class="row row-cols-1 row-cols-md-2 g-4">
        @foreach (var recipe in Recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <div class="d-flex justify-content-between align-items-center">
                            <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary">View Recipe</a>
                            @if (recipe.RatingCount > 0)
                            {
                                <small class="text-muted">
                                    ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                                </small>
                            }
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<RecipeHub.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        CategoryName = System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(CategoryName.ToLowerInvariant());
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services

@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="">Home</a></li>
        @if (Recipe is not null)
        {
            <li class="breadcrumb-item"><a href="@($"category/{Recipe.Category.ToLowerInvariant()}")">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        }
    </ol>
</nav>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <h1 class="mb-2">@Recipe.Title</h1>
    <p class="lead text-muted">@Recipe.Description</p>
    <span class="badge bg-secondary mb-4">@Recipe.Category</span>

    <div class="row mt-4">
        <div class="col-md-5">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">🧾 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-7">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">📝 Steps</h5></div>
                <div class="card-body">
                    <ol class="mb-0">
                        @foreach (var step in Recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>

    <div class="card mt-3">
        <div class="card-body">
            <h5>Rate this Recipe</h5>
            <StarRating RecipeId="Recipe.Id" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services

@inject RecipeService RecipeService

<div class="d-flex align-items-center gap-3">
    <div class="star-rating" style="font-size: 1.8rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => SubmitRating(star)"
                  @onmouseover="() => HoverRating = star"
                  @onmouseout="() => HoverRating = 0"
                  style="color: @(star <= DisplayRating ? "gold" : "#ccc"); transition: color 0.15s;">
                ★
            </span>
        }
    </div>

    @if (Submitted)
    {
        <span class="text-success fw-bold">Thanks for rating!</span>
    }
    else if (CurrentRecipe is not null && CurrentRecipe.RatingCount > 0)
    {
        <small class="text-muted">
            @CurrentRecipe.AverageRating.ToString("F1") avg (@CurrentRecipe.RatingCount ratings)
        </small>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int HoverRating { get; set; }
    private int SelectedRating { get; set; }
    private bool Submitted { get; set; }

    private RecipeHub.Models.Recipe? CurrentRecipe => RecipeService.GetRecipeById(RecipeId);
    private int DisplayRating => HoverRating > 0 ? HoverRating : SelectedRating;

    private void SubmitRating(int stars)
    {
        if (Submitted) return;
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services

@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="">Home</a></li>
        <li class="breadcrumb-item active">Submit a Recipe</li>
    </ol>
</nav>

<h1 class="mb-4">Submit a Recipe</h1>

@if (SubmittedRecipe is not null)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Recipe submitted!</h4>
        <p>Your recipe "<strong>@SubmittedRecipe.Title</strong>" has been added.</p>
        <a href="@($"recipe/{SubmittedRecipe.Id}")" class="btn btn-primary me-2">View Recipe</a>
        <button class="btn btn-outline-secondary" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Icon @cat.Name</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="description" class="form-label">Short Description</label>
            <InputText id="description" class="form-control" @bind-Value="Submission.Description" placeholder="A brief description of your recipe" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Submission.Ingredients"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Submission.Steps"
                placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
        </div>

        <button type="submit" class="btn btn-success btn-lg"
                disabled="@(!IsFormValid)">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private Recipe? SubmittedRecipe { get; set; }

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(Submission.Title) &&
        !string.IsNullOrWhiteSpace(Submission.Category) &&
        !string.IsNullOrWhiteSpace(Submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(Submission.Steps);

    private void HandleSubmit()
    {
        if (!IsFormValid) return;
        SubmittedRecipe = RecipeService.AddRecipe(Submission);
    }

    private void ResetForm()
    {
        Submission = new RecipeSubmission();
        SubmittedRecipe = null;
    }
}

