</nav>

<h1 class="mb-4">Submit a Recipe</h1>

@if (SubmittedRecipe is not null)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Recipe submitted!</h4>
        <p>Your recipe "<strong>@SubmittedRecipe.Title</strong>" has been added.</p>
        <a href="@($"recipe/{SubmittedRecipe.Id}")" class="btn btn-primary me-2">View Recipe</a>
        <button class="btn btn-outline-secondary" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Icon @cat.Name</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="description" class="form-label">Short Description</label>
            <InputText id="description" class="form-control" @bind-Value="Submission.Description" placeholder="A brief description of your recipe" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Submission.Ingredients"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Submission.Steps"
                placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
        </div>

        <button type="submit" class="btn btn-success btn-lg"
                disabled="@(!IsFormValid)">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private Recipe? SubmittedRecipe { get; set; }

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(Submission.Title) &&
        !string.IsNullOrWhiteSpace(Submission.Category) &&
        !string.IsNullOrWhiteSpace(Submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(Submission.Steps);

    private void HandleSubmit()
    {
        if (!IsFormValid) return;
        SubmittedRecipe = RecipeService.AddRecipe(Submission);
    }

    private void ResetForm()
    {
        Submission = new RecipeSubmission();
        SubmittedRecipe = null;
    }
}

